{
  "status": "ok",
  "data": {
    "as_of": "2018-11-29",
    "lookback_days": 365,
    "n_entries_total": 53,
    "n_entries_visible": 21,
    "entries": [
      {
        "entry_date": "2018-01-22",
        "body": "Trump approves Section 201 safeguard tariffs on solar panels and washing machines (China among suppliers hit). First major tariff action of the administration."
      },
      {
        "entry_date": "2018-03-01",
        "body": "Trump announces plan to impose 25% tariff on steel and 10% on aluminum imports (Section 232). Global scope; China is a smaller direct supplier share than some other exporters."
      },
      {
        "entry_date": "2018-03-02",
        "body": "Trump tweets: \"trade wars are good, and easy to win.\""
      },
      {
        "entry_date": "2018-03-08",
        "body": "Trump signs Section 232 proclamations imposing the steel (25%) and aluminum (10%) tariffs."
      },
      {
        "entry_date": "2018-03-22",
        "body": "USTR releases Section 301 report finding China's IP/tech-transfer practices unreasonable or discriminatory. Trump signs presidential memorandum directing tariffs on Chinese imports, a WTO case, and investment restrictions. USTR to publish a proposed tariff list."
      },
      {
        "entry_date": "2018-04-02",
        "body": "China imposes retaliatory tariffs on about $3B of US goods (pork, fruit, nuts, wine, and related items) in response to Section 232 steel/aluminum tariffs."
      },
      {
        "entry_date": "2018-04-03",
        "body": "USTR publishes proposed Section 301 tariff list: ~1,300 Chinese product lines (~$50B), targeting aerospace, ICT, robotics, machinery and related sectors. Public comment process opens."
      },
      {
        "entry_date": "2018-04-04",
        "body": "China announces proposed retaliatory tariffs on ~$50B of US goods (including soybeans, automobiles, and aircraft) in response to the Section 301 list."
      },
      {
        "entry_date": "2018-04-16",
        "body": "US Commerce Department bans ZTE from buying US components (denial order). ZTE faces operational shutdown. Major non-tariff escalation."
      },
      {
        "entry_date": "2018-05-19",
        "body": "US and China release joint statement after talks: China agrees to \"significantly increase\" purchases of US goods and services. Mnuchin says trade war is \"on hold.\" Markets rally."
      },
      {
        "entry_date": "2018-05-29",
        "body": "White House announces the US will proceed with Section 301 actions, including 25% tariffs on ~$50B of Chinese imports. Truce collapses."
      },
      {
        "entry_date": "2018-06-15",
        "body": "USTR announces final two-stage $50B tariff plan: 25% on List 1 (~$34B, 818 lines, effective July 6) and List 2 (~$16B, later). China announces matching retaliation the same day."
      },
      {
        "entry_date": "2018-06-18",
        "body": "Trump directs USTR to identify an additional ~$200B of Chinese imports for 10% tariffs if China retaliates against the $50B action."
      },
      {
        "entry_date": "2018-07-06",
        "body": "List 1 tariffs take effect: US 25% on ~$34B of Chinese goods. China imposes matching ~$34B retaliation the same day."
      },
      {
        "entry_date": "2018-07-10",
        "body": "USTR publishes proposed List 3: ~$200B of Chinese imports for an additional 10% tariff (~6,000 product lines). Public comment / hearing process begins."
      },
      {
        "entry_date": "2018-08-01",
        "body": "At Trump's direction, USTR says it is considering raising the proposed List 3 rate from 10% to 25%."
      },
      {
        "entry_date": "2018-08-23",
        "body": "List 2 tariffs take effect: US 25% on ~$16B (completing the $50B package). China imposes matching ~$16B retaliation."
      },
      {
        "entry_date": "2018-09-17",
        "body": "Trump directs USTR to finalize List 3: 10% tariffs on ~$200B of Chinese imports effective Sept 24, scheduled to rise to 25% on Jan 1, 2019."
      },
      {
        "entry_date": "2018-09-18",
        "body": "USTR publishes the finalized List 3 (5,745 lines after removing some consumer/electronics and other products from the July proposal)."
      },
      {
        "entry_date": "2018-09-24",
        "body": "List 3 takes effect at 10%. China imposes retaliatory tariffs (5–10%) on ~$60B of US goods. Combined US Section 301 coverage now ~$250B of Chinese imports."
      },
      {
        "entry_date": "2018-11-01",
        "body": "Trump and Xi hold a phone call focused on trade; agree to meet at the G20 in Argentina."
      }
    ]
  }
}

